const parse = (s) => { if (!s) return null; const d = new Date(String(s).replace(' ', 'T')); return isNaN(d) ? null : d; };
const ymd = (d) => d.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });
const hourBerlin = (d) => parseInt(new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Berlin', hour: '2-digit', hourCycle: 'h23' }).format(d), 10);
const fmtDe = (d) => d ? d.toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric' }) : '';
// Beginn des Folgetags (Berlin) nach dem Berlin-Tag von d = Ende des Anmeldeschluss-Tages
const nextMidnight = (d) => {
  const [y, m, dd] = ymd(d).split('-').map(Number);
  const n = new Date(Date.UTC(y, m - 1, dd + 1));
  const target = n.toISOString().slice(0, 10);
  for (const off of [1, 2]) {
    const t = new Date(n.getTime() - off * 3600000);
    if (ymd(t) === target && hourBerlin(t) === 0) return t;
  }
  return new Date(n.getTime() - 3600000);
};

const items = ($input.first().json.items) || [];
const now = new Date();
const DAY = 86400000;
const h = hourBerlin(now);
const senden = h >= 8 && h < 20;
const LINK = 'https://n8n.runrebels.com/webhook/zahlen?t=';
const out = [];
for (const b of items) {
  const tn = b.expand && b.expand.teilnehmer;
  const ev = tn && tn.expand && tn.expand.event;
  const schluss = ev && parse(ev.anmeldeschluss);
  if (!tn || !ev || !schluss) continue;
  const ende = nextMidnight(schluss);
  const kind = tn.kategorie === 'kind';
  const an = kind ? (tn.eltern_email || tn.email) : tn.email;
  const vorname = String((kind ? tn.eltern_name : tn.name) || '').split(' ')[0];
  const gruss = vorname ? 'Hallo ' + vorname + ',' : 'Hallo,';
  const wer = kind ? ('die Anmeldung von ' + (tn.name || 'deinem Kind')) : 'deine Anmeldung';
  const frist = fmtDe(schluss);
  const basis = { bestellung_id: b.id, teilnehmer_id: tn.id, an };
  const sig = ['', 'Dein RunRebels-Team', 'ein Angebot von ASCENSUS'];
  let aktion = null, betreff = '', zeilen = [], bpatch = null, tpatch = null;

  if (now >= ende) {
    if (!senden) continue;
    aktion = 'verfall';
    betreff = ev.name + ' – deine Anmeldung ist verfallen';
    zeilen = [gruss, '', wer + ' für ' + ev.name + ' ist verfallen, weil bis zum Anmeldeschluss (' + frist + ') keine Zahlung eingegangen ist.',
      '', 'Deine Daten löschen wir in 30 Tagen. Hast du die Zahlung nur verpasst? Dann schreib uns kurz an runner@runrebels.com.'];
    bpatch = { status: 'verfallen' }; tpatch = { status: 'verfallen' };
  } else if (senden && b.zahlungs_token) {
    const angemeldet = parse(tn.agb_akzeptiert_am) || parse(b.created);
    const e1 = parse(b.erinnerung1_gesendet), e2 = parse(b.erinnerung2_gesendet);
    const link = LINK + b.zahlungs_token;
    if (!e1 && angemeldet && now - angemeldet >= DAY) {
      aktion = 'erinnerung1';
      betreff = ev.name + ' – dein Startplatz wartet';
      zeilen = [gruss, '', wer + ' für ' + ev.name + ' ist angekommen, aber die Zahlung fehlt noch. Dein Startplatz ist erst sicher, wenn bezahlt ist.',
        '', 'Hier geht es direkt zur Zahlung:', link, '', 'Anmeldeschluss ist der ' + frist + '. Wer bis dahin nicht bezahlt hat, fällt aus der Liste.',
        '', 'Schon bezahlt? Dann ist diese Mail überholt, die Bestätigung kommt in Kürze. Fragen? runner@runrebels.com'];
      bpatch = { erinnerung1_gesendet: now.toISOString().replace('T', ' ') };
    } else if (e1 && !e2 && now >= new Date(ende.getTime() - 4 * DAY) && now - e1 >= DAY) {
      aktion = 'erinnerung2';
      betreff = ev.name + ' – letzte Erinnerung';
      zeilen = [gruss, '', 'bald ist Schluss: Der Anmeldeschluss für ' + ev.name + ' ist der ' + frist + ', und deine Zahlung fehlt noch.',
        '', 'Hier zahlst du in einem Schritt:', link, '', 'Nach dem ' + frist + ' verfällt die Anmeldung, und wir löschen deine Daten nach 30 Tagen.',
        '', 'Schon bezahlt? Dann ignoriere diese Mail. Fragen? runner@runrebels.com'];
      bpatch = { erinnerung2_gesendet: now.toISOString().replace('T', ' ') };
    }
  }
  if (!aktion) continue;
  out.push({ json: Object.assign({}, basis, { aktion, betreff, text: zeilen.concat(sig).join('\n'), bestellung_patch: bpatch, teilnehmer_patch: tpatch }) });
}
return out;

